//////////////////////////////////////////////////////////////
//
// Irregular Golden Tiling, mla, 2023
//
// A square can be dissected into a smaller square and two
// golden rectangles (of different sizes). A golden rectangle
// can be dissected into a square and a (smaller) golden
// rectangle. Repeat as required.
//
// 'x': show tile distance field
// 'y': iterate to fixed tile size
// 'z': progressive
//
//////////////////////////////////////////////////////////////

void mainImage(out vec4 fragColor, vec2 fragCoord) {
  const float phi = 0.5*(sqrt(5.0)-1.0); // 0.618..
  float lwidth = 0.001;
  vec2 p = 1.1*(2.0*fragCoord - iResolution.xy)/iResolution.y;
  float px = fwidth(p.x);
  vec3 col = vec3(1,1,0.5);
  vec2 a = vec2(-1.0-phi,-1);
  vec2 b = vec2(1.0+phi,1);
  int type = 1;
  float d = rectdist(p,a,b);
  if (d < 0.0) {
    uint h = uint(iTime);
    int N = 11;
    if (key(CHAR_Z)) { N = int(iTime)%14; h = uint(iTime)/14u; }
    // Could also iterate eg. until length(a-b) < 0.1
    // Or don't count thin rectangles
    // Or randomly terminate loop early.
    for (int i = 0; 
         key(CHAR_Y) ? length(a-b) > 0.1 : i < N || type == 2; 
         i++, h = ihash(h^uint(type))) {
      if (type == 0) {
        bool flip = bool(h&1u);
        if (flip) { p = p.yx; a = a.yx; b = b.yx; }
        bool reverse = bool(h&2u);
        if (reverse) {
          float x1 = phi*a.x + (1.0-phi)*b.x;
          if (p.x < x1) { b = vec2(x1,b.y); type = 2; }
          else { a = vec2(x1,a.y); type = 1; }
        } else {
          float x1 = (1.0-phi)*a.x + phi*b.x;
          if (p.x < x1) { b = vec2(x1,b.y); type = 1; }
          else { a = vec2(x1,a.y); type = 2; }
        }
        if (flip) { p = p.yx; a = a.yx; b = b.yx; }
      } else { // type == 1 || type == 2 ie. golden or thin rectangle
        bool flip = b.y-a.y > b.x-a.x;
        if (flip) { p = p.yx; a = a.yx; b = b.yx; }
        bool reverse = bool(h&1u);
        if (reverse) {
          float x1 = b.x-(b.y-a.y);
          if (p.x < x1) { b = vec2(x1,b.y); type = 1; }
          else { a = vec2(x1,a.y); type = 0; }
        } else {
          float x1 = a.x+b.y-a.y;
          if (p.x < x1) { b = vec2(x1,b.y); type = 0; }
          else { a = vec2(x1,a.y); type = 1; }
        }
        if (flip) { p = p.yx; a = a.yx; b = b.yx; }
      }
    }
    col = 0.25+0.75*h2rgb(float(h)/exp2(32.0));
    d = min(min(p.x-a.x,b.x-p.x),
            min(p.y-a.y,b.y-p.y));
    if (key(CHAR_X)) col *= 0.75-0.25*cos(PI*d/px);
  }
  col *= smoothstep(0.0,px,d-lwidth);
  col = pow(col,vec3(0.4545));
  fragColor = vec4(col,1);
}

