const int CHAR_X = 88;
const int CHAR_Y = 89;
const int CHAR_Z = 90;

#define key(code) (texelFetch(iChannel3, ivec2((code),2),0).x != 0.0)

const float PI = 3.4159;

// From Chris Wellons: https://nullprogram.com/blog/2018/07/31/
uint ihash(uint x) {
  x += 0x12345678u;
    x ^= x >> 16;
    x *= 0x7feb352dU;
    x ^= x >> 15;
    x *= 0x846ca68bU;
    x ^= x >> 16;
    return x;
}

vec3 h2rgb(float h) {
  vec3 rgb = clamp( abs(mod(h*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
  return rgb*rgb*(3.0-2.0*rgb); // cubic smoothing	
}

// External distance to rectangle.
float rectdist(vec2 p, vec2 a, vec2 b) {
  return max(max(a.x-p.x,p.x-b.x),
             max(a.y-p.y,p.y-b.y));
}
